/**
 * Loading placeholder that holds the layout while content arrives (`design/components/skeleton.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/skeleton.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, ViewEncapsulation, input } from '@angular/core'

import { MEMBER_PROVIDERS, derived, useMember, type SpaceStep } from '@polymorph/angular'
import styles from '@polymorph/recipes/structure/skeleton.module.css'

export type SkeletonShape = NonNullable<SkeletonProps['shape']>

/** Loading placeholder that holds the layout while content arrives: the inputs it takes, by the React member's prop names. */
export interface SkeletonProps {
  /**
   * Set when the skeleton stands for a named region; makes the root a `role="status"` with this
   * name. Otherwise it is hidden, because a grey box means nothing to a screen reader.
   */
  label?: string
  shape?: 'text' | 'rect' | 'circle'
  size?: SpaceStep
  /**
   * The step whose line box this stands in for.
   */
  textStep?: 'sm' | 'md' | 'lg' | 'xs' | 'xl' | '2xl' | '3xl'
  /**
   * A space step, or the full width of whatever holds it.
   */
  width?: SpaceStep | 'full'
}

/** Loading placeholder that holds the layout while content arrives. */
@Component({
  selector: 'pm-skeleton',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  // prettier-ignore
  template: `<div
[attr.class]="e1()"
[attr.data-shape]="e2()"
[attr.data-text-step]="e3()"
[attr.data-width]="e4()"
[attr.data-size]="e5()"
[attr.role]="e6()"
[attr.aria-label]="e7()"
[attr.aria-hidden]="e8()"
data-member="skeleton"
></div>`,
})
export class Skeleton {
  /**
   * Set when the skeleton stands for a named region; makes the root a `role="status"` with this
   * name. Otherwise it is hidden, because a grey box means nothing to a screen reader.
   */
  readonly label = input<SkeletonProps['label']>(undefined)
  readonly shape = input<Exclude<SkeletonProps['shape'], undefined>, SkeletonProps['shape']>(
    'text',
    { transform: (value: SkeletonProps['shape']) => (value === undefined ? 'text' : value) },
  )
  readonly size = input<SkeletonProps['size']>(undefined)
  /**
   * The step whose line box this stands in for.
   */
  readonly textStep = input<SkeletonProps['textStep']>(undefined)
  /**
   * A space step, or the full width of whatever holds it.
   */
  readonly width = input<SkeletonProps['width']>(undefined)
  protected readonly $ = useMember({
    events: [],
    props: {
      label: () => this.label(),
      shape: () => this.shape(),
      size: () => this.size(),
      textStep: () => this.textStep(),
      width: () => this.width(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly step = derived(() =>
    this.$p.shape === 'text' ? (this.$p.textStep ?? 'md') : undefined,
  )
  protected readonly span = derived(() =>
    this.$p.shape === 'circle' ? undefined : (this.$p.width ?? 'full'),
  )
  protected readonly named = derived(() => this.$p.label !== undefined)

  protected e1() {
    return styles.skeleton
  }

  protected e2() {
    return this.$p.shape
  }

  protected e3() {
    return this.step.value
  }

  protected e4() {
    return this.span.value === undefined ? undefined : String(this.span.value)
  }

  protected e5() {
    return this.$p.size === undefined ? undefined : String(this.$p.size)
  }

  protected e6() {
    return this.named.value ? 'status' : undefined
  }

  protected e7() {
    return this.$p.label
  }

  protected e8() {
    return !this.named.value ? true : undefined
  }
}
